CREATE TABLE IF NOT EXISTS "exercise_type" (
	"exercise_type_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"exercise_name" TEXT,
	"exercise_description" TEXT,
	"muscle_groups" TEXT,
	"machine_used" TEXT,
	"created_at" TIMESTAMP,
	PRIMARY KEY("exercise_type_id")
);

CREATE TABLE IF NOT EXISTS "workout_exercise" (
	"workout_exercise_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"workout_id" INTEGER NOT NULL,
	"exercise_type_id" INTEGER NOT NULL,
	"exercise_order_num" INTEGER,
	"minutes_to_complete" INTEGER,
	"created_at" TIMESTAMP,
	PRIMARY KEY("workout_exercise_id")
);

CREATE TABLE IF NOT EXISTS "exercise_set" (
	"exercise_set_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"workout_exercise_id" INTEGER NOT NULL,
	"set_order_num" INTEGER,
	"weight_lbs" NUMERIC,
	"repetitions" INTEGER,
	"cardio_incline" NUMERIC,
	"cardio_distance_mi" NUMERIC,
	"cardio_speed_mph" NUMERIC,
	"duration_min" TEXT,
	"created_at" TIMESTAMP,
	PRIMARY KEY("exercise_set_id")
);

CREATE TABLE IF NOT EXISTS "workout" (
	"workout_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"workout_date" DATE,
	"workout_duration_min" INTEGER,
	"created_at" TIMESTAMP,
	PRIMARY KEY("workout_id")
);

ALTER TABLE "workout_exercise"
ADD FOREIGN KEY("workout_id") REFERENCES "workout"("workout_id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "exercise_set"
ADD FOREIGN KEY("workout_exercise_id") REFERENCES "workout_exercise"("workout_exercise_id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
ALTER TABLE "workout_exercise"
ADD FOREIGN KEY("exercise_type_id") REFERENCES "exercise_type"("exercise_type_id")
ON UPDATE NO ACTION ON DELETE NO ACTION;